package com.nexa.business.service;

import com.nexa.business.domain.*;
import com.nexa.business.dto.*;
import com.nexa.business.repository.*;
import org.springframework.data.domain.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class BusinessService {
 private final ProductRepository products; private final CustomerRepository customers; private final SupplierRepository suppliers; private final SaleRepository sales; private final AuditService audit;
 public BusinessService(ProductRepository p,CustomerRepository c,SupplierRepository sp,SaleRepository sa,AuditService a){products=p;customers=c;suppliers=sp;sales=sa;audit=a;}
 private String actor(Authentication a){return a==null?"system":a.getName();}

 @Transactional(readOnly=true)
 public Page<Product> products(String search,int page,int size){Pageable pg=PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),1000),Sort.by("name").ascending());String q=search==null?"":search.trim();return q.isEmpty()?products.findAll(pg):products.findByNameContainingIgnoreCaseOrSkuContainingIgnoreCase(q,q,pg);}
 @Transactional public Product createProduct(ProductRequest r,Authentication a){String sku=r.getSku().trim().toUpperCase(Locale.ROOT);products.findBySkuIgnoreCase(sku).ifPresent(x->{throw new IllegalArgumentException("SKU sudah digunakan.");});Product p=new Product();apply(p,r,sku);Product saved=products.save(p);audit.log(actor(a),"CREATE","PRODUCT","Menambah produk "+saved.getSku()+" - "+saved.getName());return saved;}
 @Transactional public Product updateProduct(long id,ProductRequest r,Authentication a){Product p=products.findById(id).orElseThrow(()->new NoSuchElementException("Produk tidak ditemukan."));String sku=r.getSku().trim().toUpperCase(Locale.ROOT);products.findBySkuIgnoreCase(sku).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new IllegalArgumentException("SKU sudah digunakan.");});apply(p,r,sku);Product saved=products.save(p);audit.log(actor(a),"UPDATE","PRODUCT","Mengubah produk "+saved.getSku()+" - "+saved.getName());return saved;}
 @Transactional public void deleteProduct(long id,Authentication a){Product p=products.findById(id).orElseThrow(()->new NoSuchElementException("Produk tidak ditemukan."));if(sales.findAll().stream().anyMatch(s->Objects.equals(s.getProductId(),id)))throw new IllegalStateException("Produk sudah memiliki transaksi dan tidak dapat dihapus.");products.delete(p);audit.log(actor(a),"DELETE","PRODUCT","Menghapus produk "+p.getSku()+" - "+p.getName());}
 private void apply(Product p,ProductRequest r,String sku){p.setSku(sku);p.setName(r.getName().trim());p.setDescription(r.getDescription()==null?"":r.getDescription().trim());p.setPrice(r.getPrice());p.setStock(r.getStock());p.setUpdatedAt(Instant.now());}

 @Transactional(readOnly=true) public Page<Customer> customers(String search){Pageable pg=PageRequest.of(0,1000,Sort.by("name"));String q=search==null?"":search.trim();return q.isEmpty()?customers.findAll(pg):customers.findByNameContainingIgnoreCaseOrCodeContainingIgnoreCase(q,q,pg);}
 @Transactional public Customer createCustomer(CustomerRequest r,Authentication a){Customer c=new Customer();c.setCode("CUS-"+uniqueSuffix());apply(c,r);Customer saved=customers.save(c);audit.log(actor(a),"CREATE","CUSTOMER","Menambah customer "+saved.getCode()+" - "+saved.getName());return saved;}
 @Transactional public Customer updateCustomer(long id,CustomerRequest r,Authentication a){Customer c=customers.findById(id).orElseThrow(()->new NoSuchElementException("Customer tidak ditemukan."));apply(c,r);Customer saved=customers.save(c);audit.log(actor(a),"UPDATE","CUSTOMER","Mengubah customer "+saved.getCode()+" - "+saved.getName());return saved;}
 @Transactional public void deleteCustomer(long id,Authentication a){Customer c=customers.findById(id).orElseThrow(()->new NoSuchElementException("Customer tidak ditemukan."));customers.delete(c);audit.log(actor(a),"DELETE","CUSTOMER","Menghapus customer "+c.getCode()+" - "+c.getName());}
 private void apply(Customer c,CustomerRequest r){c.setName(r.getName().trim());c.setPhone(trim(r.getPhone()));c.setEmail(trim(r.getEmail()));c.setCity(trim(r.getCity()));c.setStatus(r.getStatus()==null||r.getStatus().trim().isEmpty()?"ACTIVE":r.getStatus().trim().toUpperCase(Locale.ROOT));c.setUpdatedAt(Instant.now());}

 @Transactional(readOnly=true) public Page<Supplier> suppliers(String search){Pageable pg=PageRequest.of(0,1000,Sort.by("name"));String q=search==null?"":search.trim();return q.isEmpty()?suppliers.findAll(pg):suppliers.findByNameContainingIgnoreCaseOrCodeContainingIgnoreCase(q,q,pg);}
 @Transactional public Supplier createSupplier(SupplierRequest r,Authentication a){Supplier s=new Supplier();s.setCode("SUP-"+uniqueSuffix());apply(s,r);Supplier saved=suppliers.save(s);audit.log(actor(a),"CREATE","SUPPLIER","Menambah supplier "+saved.getCode()+" - "+saved.getName());return saved;}
 @Transactional public Supplier updateSupplier(long id,SupplierRequest r,Authentication a){Supplier s=suppliers.findById(id).orElseThrow(()->new NoSuchElementException("Supplier tidak ditemukan."));apply(s,r);Supplier saved=suppliers.save(s);audit.log(actor(a),"UPDATE","SUPPLIER","Mengubah supplier "+saved.getCode()+" - "+saved.getName());return saved;}
 @Transactional public void deleteSupplier(long id,Authentication a){Supplier s=suppliers.findById(id).orElseThrow(()->new NoSuchElementException("Supplier tidak ditemukan."));suppliers.delete(s);audit.log(actor(a),"DELETE","SUPPLIER","Menghapus supplier "+s.getCode()+" - "+s.getName());}
 private void apply(Supplier s,SupplierRequest r){s.setName(r.getName().trim());s.setContact(trim(r.getContact()));s.setPhone(trim(r.getPhone()));s.setEmail(trim(r.getEmail()));s.setCity(trim(r.getCity()));s.setUpdatedAt(Instant.now());}

 @Transactional(readOnly=true) public Page<Sale> sales(){return sales.findAllByOrderByCreatedAtDesc(PageRequest.of(0,1000));}
 @Transactional public Sale createSale(SaleRequest r,Authentication a){Product p=products.findById(r.getProductId()).orElseThrow(()->new NoSuchElementException("Produk tidak ditemukan."));if(r.getQuantity()>p.getStock())throw new IllegalArgumentException("Stok tidak mencukupi. Tersedia "+p.getStock()+" unit.");p.setStock(p.getStock()-r.getQuantity());p.setUpdatedAt(Instant.now());products.save(p);Sale s=new Sale();s.setInvoiceNo("INV-"+DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss").withZone(ZoneId.of("Asia/Jakarta")).format(Instant.now())+"-"+uniqueSuffix().substring(2));s.setProductId(p.getId());s.setProductName(p.getName());s.setCustomerName(r.getCustomerName().trim());s.setQuantity(r.getQuantity());s.setUnitPrice(p.getPrice());s.setTotal(p.getPrice().multiply(BigDecimal.valueOf(r.getQuantity())));s.setPaymentMethod(r.getPaymentMethod().trim());s.setCashier(actor(a));s.setStatus("PAID");s.setCreatedAt(Instant.now());Sale saved=sales.save(s);audit.log(actor(a),"CREATE","SALE","Transaksi "+saved.getInvoiceNo()+" - "+saved.getProductName()+" x"+saved.getQuantity());return saved;}

 @Transactional(readOnly=true) public Map<String,Object> dashboard(){List<Product> ps=products.findAll();List<Sale> ss=sales.findAll();BigDecimal inv=ps.stream().map(p->p.getPrice().multiply(BigDecimal.valueOf(p.getStock()))).reduce(BigDecimal.ZERO,BigDecimal::add);int stock=ps.stream().mapToInt(Product::getStock).sum();long low=ps.stream().filter(p->p.getStock()<=5).count(),out=ps.stream().filter(p->p.getStock()==0).count();LocalDate today=LocalDate.now(ZoneId.of("Asia/Jakarta"));BigDecimal todayRev=ss.stream().filter(s->LocalDate.ofInstant(s.getCreatedAt(),ZoneId.of("Asia/Jakarta")).equals(today)).map(Sale::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> m=new LinkedHashMap<>();m.put("products",ps.size());m.put("stock",stock);m.put("inventoryValue",inv);m.put("lowStock",low);m.put("outOfStock",out);m.put("customers",customers.count());m.put("suppliers",suppliers.count());m.put("salesCount",ss.size());m.put("revenueToday",todayRev);return m;}
 @Transactional(readOnly=true) public Map<String,Object> notifications(){List<Product> critical=products.findAll().stream().filter(p->p.getStock()<=5).sorted(Comparator.comparingInt(Product::getStock)).collect(Collectors.toList());Map<String,Object> m=new LinkedHashMap<>();m.put("count",critical.size());m.put("content",critical);return m;}
 @Transactional(readOnly=true) public Map<String,Object> reports(){List<Sale> ss=sales.findAll();BigDecimal rev=ss.stream().map(Sale::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal avg=ss.isEmpty()?BigDecimal.ZERO:rev.divide(BigDecimal.valueOf(ss.size()),2,java.math.RoundingMode.HALF_UP);Map<String,BigDecimal> byProduct=new HashMap<>();for(Sale s:ss)byProduct.merge(s.getProductName(),s.getTotal(),BigDecimal::add);Map.Entry<String,BigDecimal> top=byProduct.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);ZoneId zone=ZoneId.of("Asia/Jakarta");LocalDate now=LocalDate.now(zone);List<Map<String,Object>> daily=new ArrayList<>();for(int i=6;i>=0;i--){LocalDate d=now.minusDays(i);BigDecimal v=ss.stream().filter(s->LocalDate.ofInstant(s.getCreatedAt(),zone).equals(d)).map(Sale::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> item=new LinkedHashMap<>();item.put("date",d.toString());item.put("value",v);daily.add(item);}Map<String,Object> m=new LinkedHashMap<>();m.put("revenue",rev);m.put("transactions",ss.size());m.put("averageOrder",avg);m.put("topProduct",top==null?"-":top.getKey());m.put("topProductRevenue",top==null?BigDecimal.ZERO:top.getValue());m.put("daily",daily);return m;}
 private static String trim(String s){return s==null?"":s.trim();}
 private static String uniqueSuffix(){String v=Long.toString(System.nanoTime(),36).toUpperCase(Locale.ROOT);return v.substring(Math.max(0,v.length()-8));}
}
